import{_ as p,o as t,c as e,ah as _}from"./chunks/framework.DjU4PSOm.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"philosophy/China/09. 왕양명.md","filePath":"philosophy/China/09. 왕양명.md"}'),a={name:"philosophy/China/09. 왕양명.md"};function o(b,r,s,n,i,c){return t(),e("div",null,[...r[0]||(r[0]=[_("<p>종교화<br> 격물 실패<br> 마음에서 찾음 심외무리, 심즉리 주장</p><p>주자학 격물치지를 즉물궁리라고 표현 비판<br> 마음에서 사물의 리를 구하므로 심과 리가 구분됨 (인식주체와 인식대상 관점)<br> 양명학에서 격물치지는 바로잡다. 치양지주장<br> 마음속의 리를 확장<br> 선지후행 비판, 지행합일 주장.<br> 앎과 행위는 다른 것이므로 알면서 행하지 않는 것은 참된 앎이 아님</p><p>심즉리, 심외무리<br> 심즉리는 마음이 곧 리.<br> 이때 마음은 본심, 양지 양명학이 마음과 리를 둘로 나누어 본 것에 대한 비판<br> 이는 심외무리로 확장<br> 마음 밖에 리가 없고 사물의 리가 내 마음 밖에 있지 않음<br> 심외무물<br> 실제로 마음 밖에 객관적 대상이 없다는 주장이 아니고<br> 내가 의식활동을 하지 않을 때, 의식 대상이 없다는 것이다.</p><p>여기 까지.</p><hr><p>양명학 시작<br> 기존의 주자학이 종교화되며 학문이 고정되어 학문으로써의 역할을 하지 못하게 됨</p><p>주자의 격물궁리를 듣고 격물을 하였으나 실패하여 주자학에 대한 회의를 품고 도가와 선불교에 관심<br> 이때 주자의 격물치지는 사물의 이치에 다가가 그 안에 있는 리를 발견하고 깨닫는 것.<br> 리는 올바름의 기준임으로 리를 알아야 올바른 행위를 할 수 있다고 주장</p><p>이후 리는 외부 사물속에서 찾는 것이 아니라 마음과 본성에서 찾아야 함을 깨달음.<br> 따라서 심외무사 심외무리, 다시말해 심즉리를 주장</p><p>즉물궁리에 대한 비판<br> 주자가 말한 격물을 즉물궁리로 표현하며 마음에서 사물의 리를 구하므로 심과 리가 분리 된다고 주장한다.<br> 주자의 주장을 마음을 인식주체로 보고 물의 내재하는 리를 인식 대상으로 구분한 것이라고 본 것이다.</p><p>양명학은 격을 바로잡다로 정의하여 내 마음에 생겨난 사사로운 욕망을 바로잡아 제거하고, 본심에 따라 선을 행하는 실천적 행위를 주장하였다<br> 따라서 치양지, 선한 본심인 양지의 확장을 주장하였다.</p><p>일상생활에서 이러한 양지가 발현되지 않는건 개인의 사욕이 이러한 양지를 가리기 때문이라고 주장한다.</p>",11)])])}const d=p(a,[["render",o]]);export{l as __pageData,d as default};
